def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max((v for row in grid for v in row), key=lambda v: sum(x == v for row in grid for x in row))
    # Each diagonal pair defines a ray. Extend from either exposed endpoint;
    # an existing non-background cell blocks that direction.
    dirs = [(1, 1), (1, -1)]
    pairs = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    # A full 2x2 block is a motif, not a diagonal line to extend.
                    # Extend only when both opposite corners are background.
                    other_a = grid[r][c + dc]
                    other_b = grid[rr][c]
                    if other_a == bg and other_b == bg:
                        pairs.add((color, r, c, rr, cc, dr, dc))
    for color, r1, c1, r2, c2, dr, dc in pairs:
        for r, c, vr, vc in ((r1, c1, -dr, -dc), (r2, c2, dr, dc)):
            rr, cc = r + vr, c + vc
            if not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] != bg:
                continue
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                out[rr][cc] = color
                rr += vr
                cc += vc
    return out

